-- 038_woody_legal_commerce_pages.sql
-- PayTR canli mod on kosulu: ticari yasal sayfalar (on bilgilendirme, mesafeli satis,
-- iptal/iade/geri odeme, teslimat/kargo). Icerik CMS custom_pages tablosunda tutulur ve
-- admin panelden duzenlenebilir (kodda gomulu marka/metin yok).
-- Idempotent: mevcut kayitlari gunceller, yenilerini ekler.

-- Ön Bilgilendirme Formu
INSERT INTO `custom_pages` (`id`, `module_key`, `is_published`, `display_order`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f11', 'preliminary_info', 1, 10)
