INSERT INTO `custom_pages_i18n` (`page_id`, `locale`, `title`, `slug`, `content`, `summary`, `meta_title`, `meta_description`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f11', 'tr', 'Ön Bilgilendirme Formu', 'on-bilgilendirme-formu', '{"html":"<p>Bu form, 6502 sayılı <strong>Tüketicinin Korunması Hakkında Kanun</strong> ve <strong>Mesafeli Sözleşmeler Yönetmeliği</strong> uyarınca, siparişinizi tamamlamadan önce tarafınıza sunulan zorunlu bilgilendirmedir. Siparişi onaylamanız, bu formu okuduğunuz ve kabul ettiğiniz anlamına gelir.</p>\\n\\n<h2>1. Satıcı Bilgileri</h2>\\n<ul>\\n  <li><strong>Satıcı Unvanı:</strong> Ayşe Polat Karakuş – Mina Yayınevi (&ldquo;Woody and Friends&rdquo;)</li>\\n  <li><strong>Adres:</strong> Yenişehir / MERSİN 33000, Türkiye</li>\\n  <li><strong>Telefon:</strong> 0324 358 03 73</li>\\n  <li><strong>WhatsApp:</strong> 0533 157 03 73</li>\\n  <li><strong>E-posta:</strong> minayayinevi@gmail.com</li>\\n  <li><strong>İnternet Sitesi:</strong> woodyvearkadaslari.com</li>\\n</ul>\\n\\n<h2>2. Alıcı Bilgileri</h2>\\n<p>Sipariş formunda tarafınızca beyan edilen ad-soyad, teslimat adresi, telefon ve e-posta bilgileri esas alınır. Bu bilgilerin doğruluğundan Alıcı sorumludur.</p>\\n\\n<h2>3. Sözleşme Konusu Ürün / Hizmet</h2>\\n<p>Sözleşmenin konusu, Alıcının sipariş anında seçtiği okul öncesi İngilizce eğitim setleri (fiziksel materyal) ve/veya dijital eğitim platformu erişimidir. Ürünün adı, adedi, satış fiyatı ve varsa kargo bedeli sipariş özeti ekranında ve sipariş onay e-postasında yer alır.</p>\\n<ul>\\n  <li>Tüm fiyatlar Türk Lirası (TRY) cinsindendir ve <strong>KDV dahildir</strong>.</li>\\n  <li>Öğrenci setleri için sitede belirtilen <strong>asgari sipariş adedi</strong> koşulu geçerlidir.</li>\\n  <li>Kampanya ve indirimler, ilan edildiği süre boyunca ve stoklarla sınırlıdır.</li>\\n</ul>\\n\\n<h2>4. Ödeme</h2>\\n<ul>\\n  <li>Ödemeler, <strong>PayTR</strong> ödeme altyapısı üzerinden kredi kartı / banka kartı ile 256-bit SSL korumalı olarak alınır.</li>\\n  <li>Kart bilgileriniz Satıcı tarafından görülmez, kaydedilmez ve saklanmaz; doğrudan lisanslı ödeme kuruluşuna iletilir.</li>\\n  <li>Taksit imkânı sunulması hâlinde, bankanızın uyguladığı vade farkı ve ek masraflar bankanız ile aranızdaki ilişkiye tabidir.</li>\\n</ul>\\n\\n<h2>5. Teslimat</h2>\\n<ul>\\n  <li>Fiziksel ürünler, ödemenin onaylanmasını takip eden <strong>1-3 iş günü</strong> içinde kargoya teslim edilir.</li>\\n  <li>Kargo süresi Türkiye geneli için ortalama <strong>2-5 iş günü</strong>dür. Yasal azami teslim süresi <strong>30 gün</strong>dür.</li>\\n  <li>Dijital platform erişimi, ödeme onayının ardından beyan ettiğiniz e-posta adresine gönderilir.</li>\\n  <li>Ayrıntı için <a href=\\"/tr/teslimat-ve-kargo\\">Teslimat ve Kargo Koşulları</a> sayfasına bakınız.</li>\\n</ul>\\n\\n<h2>6. Cayma Hakkı</h2>\\n<p>Alıcı, fiziksel ürünün teslim alındığı tarihten itibaren <strong>14 (on dört) gün</strong> içinde hiçbir gerekçe göstermeksizin ve cezai şart ödemeksizin sözleşmeden cayabilir. Cayma bildirimi <strong>minayayinevi@gmail.com</strong> adresine veya 0533 157 03 73 numarasına iletilir.</p>\\n<p><strong>Cayma hakkının kullanılamayacağı hâller</strong> (Yönetmelik m.15):</p>\\n<ul>\\n  <li>Elektronik ortamda anında ifa edilen ve tüketiciye anında teslim edilen <strong>dijital içerik ve hizmetler</strong> (platform erişimi açıldıktan sonra).</li>\\n  <li>Ambalajı açılmış, koruyucu bandı sökülmüş ses/görüntü kayıtları ile dijital materyaller.</li>\\n  <li>Alıcının isteği doğrultusunda kişiselleştirilerek hazırlanan ürünler.</li>\\n  <li>Kullanım sonucu yeniden satışa uygunluğunu yitirmiş, yıpranmış veya eksik parçalı setler.</li>\\n</ul>\\n<p>Cayma hakkı, iade ve geri ödeme süreçlerinin tamamı için <a href=\\"/tr/iade-cayma\\">İptal, İade ve Geri Ödeme Koşulları</a> sayfasına bakınız.</p>\\n\\n<h2>7. Şikâyet ve İtiraz</h2>\\n<p>Alıcı, uyuşmazlık hâlinde başvurusunu, satın alma bedeline göre yetkili <strong>Tüketici Hakem Heyetine</strong> veya <strong>Tüketici Mahkemesine</strong> yapabilir. Parasal sınırlar her yıl Ticaret Bakanlığı tarafından ilan edilir.</p>\\n<p>Öncelikle <strong>minayayinevi@gmail.com</strong> üzerinden bizimle iletişime geçmenizi rica ederiz; talepler en geç 3 iş günü içinde yanıtlanır.</p>"}', '6502 sayılı Tüketicinin Korunması Hakkında Kanun ve Mesafeli Sözleşmeler Yönetmeliği uyarınca satış öncesi zorunlu bilgilendirme.', 'Ön Bilgilendirme Formu', 'Woody and Friends satış öncesi ön bilgilendirme formu: satıcı bilgileri, ürün, ödeme, teslimat ve cayma hakkı.')
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `content` = VALUES(`content`), `summary` = VALUES(`summary`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`);

-- Mesafeli Satış Sözleşmesi
INSERT INTO `custom_pages` (`id`, `module_key`, `is_published`, `display_order`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f12', 'distance_sales', 1, 20)
ON DUPLICATE KEY UPDATE `module_key` = VALUES(`module_key`), `is_published` = VALUES(`is_published`), `display_order` = VALUES(`display_order`);

INSERT INTO `custom_pages_i18n` (`page_id`, `locale`, `title`, `slug`, `content`, `summary`, `meta_title`, `meta_description`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f12', 'tr', 'Mesafeli Satış Sözleşmesi', 'mesafeli-satis-sozlesmesi', '{"html":"<h2>MADDE 1 – TARAFLAR</h2>\\n<p><strong>SATICI</strong></p>\\n<ul>\\n  <li><strong>Unvan:</strong> Ayşe Polat Karakuş – Mina Yayınevi (&ldquo;Woody and Friends&rdquo;)</li>\\n  <li><strong>Adres:</strong> Yenişehir / MERSİN 33000, Türkiye</li>\\n  <li><strong>Telefon:</strong> 0324 358 03 73 &nbsp;|&nbsp; <strong>WhatsApp:</strong> 0533 157 03 73</li>\\n  <li><strong>E-posta:</strong> minayayinevi@gmail.com</li>\\n</ul>\\n<p><strong>ALICI</strong></p>\\n<p>Sipariş formunda ad-soyad, adres, telefon ve e-posta bilgilerini beyan eden kişidir. İşbu sözleşme, Alıcının sipariş öncesinde bu metni ve <a href=\\"/tr/on-bilgilendirme\\">Ön Bilgilendirme Formunu</a> onaylaması ile elektronik ortamda kurulur.</p>\\n\\n<h2>MADDE 2 – KONU</h2>\\n<p>İşbu sözleşmenin konusu, Alıcının woodyvearkadaslari.com internet sitesi üzerinden elektronik ortamda siparişini verdiği, aşağıda nitelikleri ve satış fiyatı belirtilen ürün/hizmetin satışı ve teslimi ile ilgili olarak 6502 sayılı Tüketicinin Korunması Hakkında Kanun ve Mesafeli Sözleşmeler Yönetmeliği hükümleri uyarınca tarafların hak ve yükümlülüklerinin belirlenmesidir.</p>\\n\\n<h2>MADDE 3 – SÖZLEŞME KONUSU ÜRÜN VE BEDEL</h2>\\n<p>Ürünün türü, adedi, marka/modeli, satış bedeli ve varsa kargo ücreti, sipariş özeti ekranında ve Alıcıya gönderilen sipariş onay e-postasında yer alır ve işbu sözleşmenin ayrılmaz parçasıdır. Listelenen fiyatlar <strong>KDV dahil</strong> Türk Lirası tutarlardır. İlan edilen fiyatlar ve vaatler, güncelleme yapılana ve değiştirilene kadar geçerlidir.</p>\\n\\n<h2>MADDE 4 – GENEL HÜKÜMLER</h2>\\n<ul>\\n  <li>4.1. Alıcı, sözleşme konusu ürünün temel nitelikleri, satış fiyatı, ödeme şekli ve teslimata ilişkin ön bilgileri okuyup bilgi sahibi olduğunu ve elektronik ortamda gerekli teyidi verdiğini kabul eder.</li>\\n  <li>4.2. Satıcı, sözleşme konusu ürünü eksiksiz, siparişte belirtilen niteliklere uygun ve varsa garanti belgeleri ve kullanım kılavuzları ile teslim etmeyi kabul eder.</li>\\n  <li>4.3. Ürün, Alıcıdan başka bir kişi/kuruluşa teslim edilecek ise, teslim edilecek kişi/kuruluşun teslimatı kabul etmemesinden Satıcı sorumlu tutulamaz.</li>\\n  <li>4.4. Satıcı, sözleşmeden doğan ifa yükümlülüğünün süresi dolmadan Alıcıyı bilgilendirmek ve açıkça onayını almak suretiyle eşit kalite ve fiyatta farklı bir ürün tedarik edebilir.</li>\\n  <li>4.5. Sipariş konusu ürünün teslimi, bedelin Satıcının hesabına geçmesi şartına bağlıdır. Ödeme gerçekleşmez veya banka kayıtlarında iptal edilirse, Satıcı teslim yükümlülüğünden kurtulmuş sayılır.</li>\\n  <li>4.6. Ürünün tesliminden sonra Alıcıya ait kredi kartının, Alıcının kusurundan kaynaklanmayan bir şekilde yetkisiz kişilerce haksız kullanılması nedeniyle bedelin ilgili banka veya finans kuruluşunca Satıcıya ödenmemesi hâlinde, Alıcı ürünü 3 gün içinde masrafları Satıcıya ait olacak şekilde iade eder.</li>\\n  <li>4.7. Mücbir sebepler ya da nakliyeyi engelleyen hava muhalefeti, ulaşımın kesilmesi gibi olağanüstü durumlar nedeniyle ürün süresinde teslim edilemezse, Satıcı durumu Alıcıya bildirir. Alıcı siparişin iptalini, benzer bir ürünle değiştirilmesini veya engel ortadan kalkana dek teslimatın ertelenmesini talep edebilir. Sipariş iptal edilirse, ödenen tutar 14 gün içinde iade edilir.</li>\\n</ul>\\n\\n<h2>MADDE 5 – TESLİMAT</h2>\\n<p>Fiziksel ürünler, ödemenin onaylanmasını takip eden 1-3 iş günü içinde kargoya verilir; Türkiye geneli ortalama teslim süresi 2-5 iş günüdür. Her hâlükârda yasal teslim süresi, siparişin Satıcıya ulaşmasından itibaren <strong>30 günü</strong> aşamaz. Dijital platform erişimi, ödeme onayının ardından Alıcının beyan ettiği e-posta adresine iletilir. Teslimat, Alıcının sipariş formunda bildirdiği adrese yapılır; hatalı veya eksik adres beyanından doğan gecikme ve ek kargo bedelinden Alıcı sorumludur.</p>\\n\\n<h2>MADDE 6 – CAYMA HAKKI</h2>\\n<p>Alıcı, fiziksel ürünün kendisine veya gösterdiği kişiye teslim edildiği tarihten itibaren <strong>14 (on dört) gün</strong> içinde, hiçbir hukuki ve cezai sorumluluk üstlenmeksizin ve gerekçe göstermeksizin sözleşmeden cayma hakkına sahiptir. Cayma bildirimi, süre içinde <strong>minayayinevi@gmail.com</strong> adresine yazılı olarak veya 0533 157 03 73 numarasına iletilir.</p>\\n<p>Satıcı, cayma bildiriminin kendisine ulaşmasından itibaren <strong>14 gün</strong> içinde, ürün bedelini ve varsa teslim masraflarını Alıcıya iade eder. Ürünün Satıcıya iade edilmesi zorunludur.</p>\\n\\n<h2>MADDE 7 – CAYMA HAKKININ KULLANILAMAYACAĞI ÜRÜNLER</h2>\\n<p>Mesafeli Sözleşmeler Yönetmeliği m.15 uyarınca aşağıdaki ürünlerde cayma hakkı kullanılamaz:</p>\\n<ul>\\n  <li>Elektronik ortamda anında ifa edilen ve tüketiciye anında teslim edilen <strong>dijital içerik ve hizmetler</strong> (platform erişimi açıldıktan sonra).</li>\\n  <li>Ambalajı/koruyucu bandı açılmış ses veya görüntü kayıtları ile dijital materyaller.</li>\\n  <li>Alıcının istekleri doğrultusunda kişiselleştirilerek hazırlanan ürünler.</li>\\n  <li>Tesliminden sonra kullanım nedeniyle yeniden satışa uygunluğunu yitiren, yıpranmış veya eksik parçalı setler.</li>\\n</ul>\\n\\n<h2>MADDE 8 – TEMERRÜT HÂLİ</h2>\\n<p>Alıcının kredi kartı ile yaptığı ödemelerde temerrüde düşmesi hâlinde, kart sahibi banka ile arasındaki kredi kartı sözleşmesi çerçevesinde bankasına karşı sorumlu olacaktır. Bu durumda ilgili banka hukuki yollara başvurabilir; doğacak masraf ve vekâlet ücretini Alıcıdan talep edebilir.</p>\\n\\n<h2>MADDE 9 – YETKİLİ MAHKEME</h2>\\n<p>İşbu sözleşmeden doğan uyuşmazlıklarda, Ticaret Bakanlığınca her yıl ilan edilen parasal sınırlar dâhilinde Alıcının veya Satıcının yerleşim yerindeki <strong>Tüketici Hakem Heyetleri</strong>, bu sınırların üzerindeki uyuşmazlıklarda <strong>Tüketici Mahkemeleri</strong> yetkilidir.</p>\\n\\n<h2>MADDE 10 – YÜRÜRLÜK</h2>\\n<p>Alıcı, sipariş ekranında işbu sözleşmeyi ve Ön Bilgilendirme Formunu okuduğunu, anladığını ve elektronik ortamda onayladığını; ödeme yükümlülüğü altına girdiğini kabul, beyan ve taahhüt eder. Sözleşme, siparişin Satıcı tarafından onaylanması ile yürürlüğe girer.</p>"}', 'İnternet üzerinden yapılan satışlarda Satıcı ile Alıcı arasındaki hak ve yükümlülükleri düzenleyen sözleşme.', 'Mesafeli Satış Sözleşmesi', 'Woody and Friends mesafeli satış sözleşmesi: taraflar, ürün, ödeme, teslimat, cayma hakkı ve uyuşmazlık çözümü.')
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `content` = VALUES(`content`), `summary` = VALUES(`summary`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`);

