INSERT INTO `custom_pages_i18n` (`page_id`, `locale`, `title`, `slug`, `content`, `summary`, `meta_title`, `meta_description`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f13', 'tr', 'İptal, İade ve Geri Ödeme Koşulları', 'iptal-iade-ve-geri-odeme-kosullari', '{"html":"<p>Woody and Friends olarak, satın aldığınız üründen memnun kalmanızı önemsiyoruz. Aşağıdaki koşullar, 6502 sayılı Tüketicinin Korunması Hakkında Kanun ve Mesafeli Sözleşmeler Yönetmeliği çerçevesinde hazırlanmıştır.</p>\\n\\n<h2>1. Sipariş İptali (Kargoya Verilmeden Önce)</h2>\\n<p>Siparişiniz henüz kargoya verilmediyse, ücretsiz olarak iptal edebilirsiniz. İptal talebinizi <strong>minayayinevi@gmail.com</strong> adresine veya <strong>0533 157 03 73</strong> WhatsApp hattına sipariş numaranızla birlikte iletmeniz yeterlidir. İptal onaylandığında ödeme tutarı iade sürecine alınır.</p>\\n\\n<h2>2. Cayma Hakkı (14 Gün)</h2>\\n<p>Fiziksel ürünlerde, ürünün size veya belirttiğiniz kişiye teslim edildiği tarihten itibaren <strong>14 (on dört) gün</strong> içinde hiçbir gerekçe göstermeden ve cezai şart ödemeden sözleşmeden cayabilirsiniz.</p>\\n<ul>\\n  <li>Cayma bildiriminizi 14 günlük süre <strong>dolmadan</strong> yazılı olarak iletmeniz gerekir.</li>\\n  <li>Bildirim kanalları: <strong>minayayinevi@gmail.com</strong> veya WhatsApp <strong>0533 157 03 73</strong>.</li>\\n  <li>Bildiriminizde sipariş numaranızı, ad-soyadınızı ve iade etmek istediğiniz ürünleri belirtiniz.</li>\\n</ul>\\n\\n<h2>3. İade Edilecek Ürünün Durumu</h2>\\n<p>İade edilecek ürünün, yeniden satılabilirliğini koruması gerekir:</p>\\n<ul>\\n  <li>Ürün, kutusu, ambalajı, varsa standart aksesuarları ve tüm parçaları ile <strong>eksiksiz</strong> olmalıdır.</li>\\n  <li>Kullanım sonucu yıpranmamış, kirlenmemiş, yazılmamış/boyanmamış olmalıdır.</li>\\n  <li>Sipariş faturası/irsaliyesi paketle birlikte gönderilmelidir.</li>\\n</ul>\\n\\n<h2>4. İade Gönderim Süreci</h2>\\n<ol>\\n  <li>Cayma bildiriminizi iletirsiniz.</li>\\n  <li>Tarafımızca <strong>en geç 2 iş günü içinde</strong> iade adresi ve anlaşmalı kargo bilgisi tarafınıza yazılı olarak bildirilir.</li>\\n  <li>Ürünü, bildirilen kargo firması ve iade kodu ile gönderirsiniz. <strong>Cayma hakkı kapsamındaki iadelerde, tarafımızca bildirilen kargo firması kullanıldığı takdirde iade kargo bedeli Satıcıya aittir.</strong> Farklı bir kargo firması tercih edilirse gönderim bedeli Alıcıya ait olur.</li>\\n  <li>Ürün tarafımıza ulaştıktan sonra kontrol edilir ve geri ödeme başlatılır.</li>\\n</ol>\\n\\n<h2>5. Geri Ödeme Süresi ve Şekli</h2>\\n<ul>\\n  <li>Geri ödeme, cayma bildiriminizin bize ulaşmasından itibaren <strong>en geç 14 gün</strong> içinde yapılır.</li>\\n  <li>İade, ödemeyi yaptığınız <strong>aynı yöntemle</strong> ve aynı karta gerçekleştirilir; nakit veya farklı bir hesaba ödeme yapılamaz.</li>\\n  <li>Kredi kartı iadelerinde tutarın kart ekstrenize yansıması, bankanızın işlem süresine bağlı olarak <strong>2-10 iş günü</strong> sürebilir. Bu süre bankanızın inisiyatifindedir.</li>\\n  <li>Taksitli alışverişlerde banka, iadeyi kart sahibine taksitler hâlinde yansıtabilir.</li>\\n</ul>\\n\\n<h2>6. Hasarlı, Ayıplı veya Eksik Ürün</h2>\\n<p>Kargo paketini teslim alırken kontrol ediniz. Pakette ezilme, yırtılma veya ıslanma varsa <strong>kargo görevlisine tutanak tutturmadan teslim almayınız</strong>. Ürün ayıplı, eksik veya siparişinizden farklı çıktıysa, teslimattan itibaren <strong>7 gün içinde</strong> fotoğraflarla birlikte bize ulaşın; ürün ücretsiz olarak değiştirilir veya bedeli iade edilir. Bu durumda tüm kargo masrafları Satıcıya aittir.</p>\\n\\n<h2>7. Cayma Hakkının Kullanılamayacağı Ürünler</h2>\\n<p>Mesafeli Sözleşmeler Yönetmeliği m.15 uyarınca aşağıdaki ürünlerde cayma hakkı bulunmamaktadır:</p>\\n<ul>\\n  <li>Elektronik ortamda anında ifa edilen <strong>dijital içerik ve platform erişimleri</strong> — erişim açıldıktan/kullanılmaya başlandıktan sonra.</li>\\n  <li>Ambalajı veya koruyucu bandı açılmış ses/görüntü kayıtları ve dijital materyaller.</li>\\n  <li>Alıcının talebi doğrultusunda kişiselleştirilerek hazırlanan ürünler.</li>\\n  <li>Kullanım nedeniyle yeniden satışa uygun olmaktan çıkmış, eksik parçalı veya yıpranmış setler.</li>\\n</ul>\\n<p>Dijital ürünlerde satın alma öncesinde tanıtım içeriklerini incelemenizi ve sorularınız için bize ulaşmanızı öneririz.</p>\\n\\n<h2>8. İletişim</h2>\\n<p>Tüm iptal, iade ve geri ödeme talepleriniz için:<br>\\nE-posta: <strong>minayayinevi@gmail.com</strong><br>\\nTelefon: <strong>0324 358 03 73</strong> &nbsp;|&nbsp; WhatsApp: <strong>0533 157 03 73</strong><br>\\nTalepler en geç <strong>3 iş günü</strong> içinde yanıtlanır.</p>"}', 'Sipariş iptali, cayma hakkı, ürün iadesi ve para iadesi süreçlerinin adım adım açıklaması.', 'İptal, İade ve Geri Ödeme Koşulları', 'Woody and Friends iptal, iade ve geri ödeme koşulları: 14 gün cayma hakkı, iade süreci, geri ödeme süresi ve istisnalar.')
