INSERT INTO `custom_pages_i18n` (`page_id`, `locale`, `title`, `slug`, `content`, `summary`, `meta_title`, `meta_description`) VALUES
('9c1f4a20-5d6e-4b71-9a03-1e7c2b8d4f14', 'tr', 'Teslimat ve Kargo Koşulları', 'teslimat-ve-kargo-kosullari', '{"html":"<p>Bu sayfa, woodyvearkadaslari.com üzerinden verdiğiniz siparişlerin hazırlanma, gönderim ve teslim süreçlerini açıklar.</p>\\n\\n<h2>1. Sipariş Hazırlık Süresi</h2>\\n<p>Ödemesi onaylanan siparişler, <strong>1-3 iş günü</strong> içinde hazırlanarak kargoya teslim edilir. Hafta sonu ve resmî tatil günleri iş günü sayılmaz; bu günlerde verilen siparişler takip eden ilk iş gününde işleme alınır.</p>\\n\\n<h2>2. Teslim Süresi</h2>\\n<ul>\\n  <li>Kargoya verilen siparişler Türkiye geneline ortalama <strong>2-5 iş günü</strong> içinde teslim edilir.</li>\\n  <li>Yoğun kampanya dönemleri, olumsuz hava koşulları ve mücbir sebepler teslim süresini uzatabilir; böyle bir durumda tarafınıza bilgi verilir.</li>\\n  <li>Yasal azami teslim süresi, siparişin tarafımıza ulaşmasından itibaren <strong>30 gündür</strong>.</li>\\n</ul>\\n\\n<h2>3. Kargo Ücreti</h2>\\n<p>Kargo bedeli, varsa sipariş özeti ekranında ürün tutarından ayrı olarak açıkça gösterilir ve ödeme öncesinde toplam tutara dâhil edilir. Ödeme adımına geçmeden önce, ödeyeceğiniz nihai tutarı sipariş özetinden görebilirsiniz. Kampanya dönemlerinde ilan edilen tutarın üzerindeki siparişlerde kargo ücretsiz olabilir.</p>\\n\\n<h2>4. Kargo Takibi</h2>\\n<p>Siparişiniz kargoya verildiğinde, kargo firması ve takip numarası beyan ettiğiniz e-posta adresine ve/veya WhatsApp numaranıza iletilir. Takip numarasının kargo firması sisteminde görünür hâle gelmesi birkaç saat sürebilir.</p>\\n\\n<h2>5. Teslimat Adresi</h2>\\n<ul>\\n  <li>Teslimat, sipariş formunda beyan ettiğiniz adrese yapılır.</li>\\n  <li>Adresin eksik veya hatalı olması nedeniyle yaşanan gecikmelerden ve doğacak <strong>ek kargo bedelinden Alıcı sorumludur</strong>.</li>\\n  <li>Adres değişikliği talebiniz varsa, sipariş kargoya verilmeden önce bize ulaşmanız gerekir.</li>\\n  <li>Adreste bulunulamaması hâlinde kargo firması genellikle 3 iş günü şubede bekletir; bu süre sonunda gönderi tarafımıza iade olur ve yeniden gönderim bedeli Alıcıya aittir.</li>\\n</ul>\\n\\n<h2>6. Teslim Alırken Dikkat Edilmesi Gerekenler</h2>\\n<p>Paketi teslim alırken <strong>kargo görevlisinin yanında kontrol ediniz</strong>. Pakette ezilme, yırtılma, ıslanma veya açılma izi varsa paketi teslim almayınız ve kargo görevlisine <strong>hasar tespit tutanağı</strong> tutturunuz. Tutanaklı olmayan hasar bildirimlerinde kargo firmasından tazmin talebinde bulunulamamaktadır. Tutanak tuttuktan sonra <strong>minayayinevi@gmail.com</strong> adresine bilgi veriniz; ürün ücretsiz olarak yenisiyle değiştirilir.</p>\\n\\n<h2>7. Dijital Ürün Teslimi</h2>\\n<p>Dijital eğitim platformu erişimleri fiziksel kargo ile gönderilmez. Ödemenin onaylanmasının ardından erişim bilgileri, sipariş sırasında beyan ettiğiniz <strong>e-posta adresine</strong> iletilir. E-posta ulaşmadıysa spam/gereksiz klasörünüzü kontrol ediniz ve bize bildiriniz.</p>\\n\\n<h2>8. İade ve Değişim</h2>\\n<p>İade, cayma hakkı ve geri ödeme süreçleri için <a href=\\"/tr/iade-cayma\\">İptal, İade ve Geri Ödeme Koşulları</a> sayfasını inceleyiniz.</p>\\n\\n<h2>9. İletişim</h2>\\n<p>Teslimat ve kargo ile ilgili tüm sorularınız için:<br>\\nE-posta: <strong>minayayinevi@gmail.com</strong><br>\\nTelefon: <strong>0324 358 03 73</strong> &nbsp;|&nbsp; WhatsApp: <strong>0533 157 03 73</strong></p>"}', 'Siparişlerin hazırlanma, kargoya verilme ve teslim süreçleri ile kargo ücretlendirmesi.', 'Teslimat ve Kargo Koşulları', 'Woody and Friends teslimat ve kargo koşulları: hazırlık süresi, teslim süresi, kargo ücreti ve teslim alma kuralları.')
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `content` = VALUES(`content`), `summary` = VALUES(`summary`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`);

